contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single test function driving contract and asserting the distinguishing property.
    // params:
    // - caller: address that will attempt to call withdrawAll (simulated by msg.sender in this contract's call)
    // - initialDeposit: amount of wei this test contract will send to C via fallback to increase its balance
    // Note: the contract's own address must hold enough Ether to forward; tests should fund it externally.
    function run(address caller, uint initialDeposit) public {
        // Preconditions: this contract must have enough balance to deposit
        require(address(this).balance >= initialDeposit);

        // Make a deposit into c by calling its fallback via a plain call with value.
        // This increments c.depositsCount and increases address(c).balance.
        (bool s,) = address(c).call{value: initialDeposit}("\x00");
        // require the deposit succeeded for the test to be meaningful
        require(s);

        // Observe c's balance before withdrawAll call
        uint balBefore = address(c).balance;

        // Attempt to call withdrawAll as this contract (msg.sender == address(this)).
        // We need to detect whether the call reverts. Use low-level call to capture success.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // If the real contract P is used, only owner (the deployer of C) can withdraw; since this
        // test contract is generally not the owner, the call should revert (ok == false) unless
        // the provided caller is actually the owner. The mutant M inverted the check so non-owners
        // can withdraw: in that case our non-owner test caller would succeed and reduce balance.
        // We assert the general rule: when this contract is NOT the owner, withdrawAll does NOT succeed
        // and so c's balance remains unchanged. Formally: if c.owner() != address(this) then
        // (ok == false) AND address(c).balance == balBefore.

        // Obtain owner via public getter
        address owner = c.owner();

        if (owner != address(this)) {
            // The distinguishing assertion: non-owner cannot successfully withdraw and balance unchanged.
            assert(ok == false && address(c).balance == balBefore);
        } else {
            // If this contract is the owner, withdrawAll should succeed and drain the contract.
            // We assert that in that case ok == true and balance decreased (or became zero).
            assert(ok == true && address(c).balance <= balBefore);
        }
    }

    // Allow funding this test contract for deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // No precondition needed; we test behavior when contract balance is zero.
        // Ensure target contract has zero balance: we do not send any ether here.
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // On the original contract, withdrawAll should revert when C has zero balance.
        // We express that by asserting it reverted.
        assert(reverted == true);
    }
    receive() external payable { }
}

