contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // caller provides amounts and then attempts withdrawAll; on original contract this must NOT give caller the contract balance
    function runTest(uint sendAmount) public payable {
        require(msg.value == 0, "do not send ether to this function");
        // ensure this contract has enough balance to forward sendAmount
        require(address(this).balance >= sendAmount, "insufficient test contract balance");

        // 1) A third party (this contract) sends Ether into c via fallback to increase depositsCount and fund c
        // Use low-level call to forward Ether to c so fallback() triggers
        (bool s,) = address(c).call{value: sendAmount}("");
        require(s, "funding c failed");

        // record balances before withdrawAll
        uint beforeCaller = address(this).balance;
        uint beforeTarget = address(c).balance;

        // 2) Attempt to call withdrawAll from this (non-owner) contract
        // This is the decisive call: in P it must revert (due to onlyOwner) and not transfer funds; in M it will succeed and transfer
        // We capture whether it reverts by using try/catch on the external call via low-level call
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // After call, check how much balance this contract gained
        uint afterCaller = address(this).balance;
        uint afterTarget = address(c).balance;

        // The distinguishing general rule: non-owner calling withdrawAll cannot increase the caller's balance by the contract's balance.
        // Expressed as: the caller's balance increase is strictly less than the contract's balance before the call.
        // On original P the call will revert so increase is 0, satisfying the assertion. On mutant M the call succeeds and transfers funds,
        // violating the assertion when sendAmount>0 because caller's balance increases by >= beforeTarget.
        assert(afterCaller - beforeCaller < beforeTarget);
    }

    // allow the test contract to receive ETH so it can fund c
    receive() external payable {}
}

