pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the deposit amount so the fuzzer can find cases where contract has nonzero balance
    function testFuzz_property(uint256 depositAmount) public {
        // keep depositAmount within reasonable bounds but wide enough
        depositAmount = bound(depositAmount, 0, 1 ether);

        // fund an external depositor EOA so it can send ETH to c via fallback
        address depositor = address(0xBEEF);
        vm.deal(depositor, depositAmount);

        if (depositAmount > 0) {
            // depositor sends ETH to c triggering fallback and increasing depositsCount and contract balance
            vm.prank(depositor);
            (bool s,) = address(c).call{value: depositAmount}("");
            require(s);
        }

        // Check precondition: contract balance equals depositAmount
        // Now owner (deployer of c) calls withdrawAll
        // In the reference, this should withdraw entire balance, leaving address(c).balance == 0
        // We observe the contract only via address(c).balance as required.
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: after owner calls withdrawAll it must be that contract balance is zero
        // (this holds for the reference for all inputs; the mutant that calls withdraw(0) will leave nonzero balance for some depositAmount > 0)
        assertTrue(address(c).balance == 0);
    }
}

