pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to deposit and an address to act as owner (prank)
    function testFuzz_property(uint128 depositAmount, address caller) public {
        // keep depositAmount in a wide but reasonable range (allow zero too)
        uint256 amt = uint256(depositAmount);
        // ensure caller is a non-zero address
        vm.assume(caller != address(0));

        // fund caller so they can send ether to the contract
        vm.deal(caller, amt + 1 ether);

        // make caller the owner: the contract sets owner = msg.sender at deployment (setUp used test contract),
        // so we must interact as that owner. The owner is address(this) (the test contract) because setUp did new C().
        // Therefore ensure withdrawAll is invoked by the original owner (the test contract). We'll send deposits from `caller`.

        // deposit into contract by sending raw Ether to fallback (increments depositsCount and increases balance)
        if (amt > 0) {
            vm.prank(caller);
            // send amt to contract's fallback
            (bool sent, ) = address(c).call{value: amt}("");
            require(sent, "funding failed");
        }

        // record balance before withdrawAll
        uint256 before = address(c).balance;

        // call withdrawAll as the owner (this test contract is the owner because it deployed C in setUp)
        // use try/catch only if needed for revert differences; here both reference and mutant are non-reverting,
        // but we still call normally.
        c.withdrawAll();

        // exactly one assertion: for the correct contract, if before > 0 then after < before (balance decreased by transfer of full balance).
        // This property is violated by the mutant which does transfer(0) and thus leaves balance unchanged for some inputs (when before > 0).
        uint256 after = address(c).balance;

        // General rule: if there was any balance to withdraw, withdrawAll reduces the contract balance (transfers it out).
        assertTrue(before == 0 || after < before);
    }
}

