contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to deposit (must be >0) and address ownerActor (fuzzer supplies)
    function testFuzz_property(uint256 depositAmount, address ownerActor) public {
        // admissible domain: depositAmount must be at least 1 and fit in contract balance payable from ownerActor
        vm.assume(depositAmount > 0);
        // ensure ownerActor is the owner in the scenario by making the created contract's owner equal to ownerActor
        // we cannot change c.owner after deployment; c.owner is msg.sender at construction (setUp used test contract).
        // To make the caller of withdrawAll be the owner, we need to deploy a fresh C with ownerActor as constructor caller.
        // Deploy a new C where owner is ownerActor by impersonating ownerActor.
