        // record pre-call contract balance
        uint256 before = address(c2).balance;
        // sanity: ensure we actually have a positive balance
        vm.assume(before > 0);

        // ownerActor calls withdrawAll
        vm.prank(ownerActor);
        // call withdrawAll; reference should transfer out entire balance, mutant transfers 0
        c2.withdrawAll();

        uint256 after = address(c2).balance;

        // General property: calling withdrawAll as the owner strictly decreases the contract balance when it is positive
        // (reference: decreases by full amount; mutant that transfers 0 will leave it unchanged for some inputs)
